-- Lock phase: all-or-nothing NOWAIT over the tables still to change, bounded at 6 s.
select set_config('restomatch.saved_statement_timeout', current_setting('statement_timeout'), true);
select set_config('statement_timeout', '6s', true);
do $$
declare r record;
begin
  if not exists (select 1 from pg_temp.rm_todo where take_lock) then
    return; -- already provisioned: no ACCESS EXCLUSIVE at all
  end if;
  loop
    begin
      for r in select distinct sch, tbl from pg_temp.rm_todo where take_lock order by sch, tbl loop
        execute format('lock table %I.%I in access exclusive mode nowait', r.sch, r.tbl);
      end loop;
      exit;
    exception when lock_not_available then
      perform pg_sleep(0.05); -- the failed attempt released every lock it took
    end;
  end loop;
end $$;
select set_config('statement_timeout', coalesce(nullif(current_setting('restomatch.saved_statement_timeout', true), ''), (select reset_val from pg_settings where name = 'statement_timeout')), true);

-- 1. The non-owner tenant role. NOLOGIN and NO password in git: after the first
--    deploy the owner runs  ALTER ROLE restomatch_app WITH LOGIN PASSWORD '…';
--    (docs/SUPABASE-GITHUB-DEPLOY.md), or provision-rls with APP_ROLE_PASSWORD.
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'restomatch_app') then
    create role restomatch_app nologin;
  end if;
end $$;

-- 2. Core tenant RLS (packages/db/drizzle/rls/0002_core_tenant_rls.sql, lock-safe rewrite)
-- ───────────────────────────────────────────────────────────────────────────
-- Per-restaurant Row-Level Security for RestoMatch core tables.
-- Apply during Phase-3 Supabase consolidation (NOT via pnpm db:migrate).
-- Also applied to the local test DB by the RLS attack suite
-- (packages/api/src/__tests__/rls.attack.test.ts) via applyCoreTenantRls().
--
-- Tenancy key: every protected row carries restaurant_id. The app sets the
-- active restaurant per transaction:  SET LOCAL app.current_restaurant_id = '<uuid>';
-- (wired in packages/api/src/trpc.ts memberProcedure via withRestaurant()).
-- Apply on a role that is NOT the table owner / NOT service_role (both bypass RLS).
--
-- The worker connects with a service (RLS-bypassing) role BY DESIGN: cron jobs
-- (baselines, daily expectations, outbox) are inherently cross-tenant. Worker
-- tenant safety relies on the explicit payload-ownership guards in its jobs.
-- ───────────────────────────────────────────────────────────────────────────

create schema if not exists app;

-- Reads the active restaurant from the per-transaction GUC (NULL if unset).
-- search_path pinned (pg_temp LAST) and every name qualified: these run inside
-- owner-run cascades and triggers too, where a planted pg_temp type must not resolve.
create or replace function app.current_restaurant_id() returns pg_catalog.uuid
  language sql stable
  set search_path = pg_catalog, pg_temp
  as $$ select nullif(pg_catalog.current_setting('app.current_restaurant_id', true), '')::pg_catalog.uuid $$;

-- Reads the acting user from the per-transaction GUC (NULL if unset).
create or replace function app.current_user_id() returns pg_catalog.uuid
  language sql stable
  set search_path = pg_catalog, pg_temp
  as $$ select nullif(pg_catalog.current_setting('app.current_user_id', true), '')::pg_catalog.uuid $$;

